334	      const query = state.featureInput.trim();
335	      const key = state.meta.features.find(feature => feature.label.toLowerCase() === query.toLowerCase() || feature.key === query)?.key || query;
336	      const features = [...new Set([...state.features, ...(key ? [key] : [])])];
337	      if (!features.length) throw new Error('Enter a feature or customer need first.');
338	      const revision = state.revision;
339	      const pendingRequest = request('evidence', '/api/decision/evidence', post({ context: contextPayload(), features }));
340	      render();
341	      const evidence = await pendingRequest;
342	      if (revision !== state.revision) return;
343	      state.evidence = evidence;
344	      state.features = list(evidence.features).map(feature => feature.id);
345	      state.featureInput = '';
346	      markDirty();
347	    } catch (error) { reportError(error, 'evidenceError'); }
348	    render();
349	  }
350	
351	  function addCandidate() {
352	    const feature = root.querySelector('#dw-add-feature')?.value;
353	    const market = root.querySelector('#dw-add-market')?.value;
354	    const action = root.querySelector('#dw-add-action')?.value;
355	    if (!feature || !market || !action) { state.runError = 'Choose a feature, market and action before adding a proposal.'; render(); return; }
356	    if (state.candidates.some(candidate => candidate.feature === feature && candidate.market === market && candidate.action === action)) { state.runError = 'This feature, action and market already has a draft candidate.'; render(); return; }
357	    if (state.candidates.length >= 16) return;
358	    const id = `C${String(state.nextId++).padStart(3, '0')}`;
359	    state.candidates.push({ id, title: `${actionLabels[action]} ${featureName(feature)} for ${marketName(market)}`, feature, market, action, impact: null, saturation: null, values: { future: null, delivery: null, regional: null, experience: null }, scenario_values: { slow: null, baseline: null, fast: null }, development_cost: null, feasibility: 'unknown', assumption_rationale: '', mandatory: false, dependencies: [], exclusions: [] });

/* Requirements Cockpit - light SaaS palette, full-viewport layout (no page scroll). */
:root {
  --bg: #ffffff;
  --surface: #f2f4f9;
  --surface-2: #e8eaf2;
  --border: #e4e7ec;
  --border-strong: #d0d5dd;
  --text-1: #111827;
  --text-2: #4b5563;
  --text-3: #9ca3af;
  --accent: #2f6fed;
  --accent-soft: #eef3fd;
  --accent-border: #bfcffb;
  --success: #059669;
  --success-soft: #ecfdf5;
  --warning: #d97706;
  --warning-soft: #fffbeb;
  --danger: #dc2626;
  --danger-soft: #fef2f2;
  --info: #0284c7;
  --info-soft: #f0f9ff;
  /* chart series (validated categorical slots) */
  --s-praise: #2a78d6;
  --s-complaint: #eb6834;
  --s-request: #1baf7a;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.04), 0 2px 6px -1px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.08);
  --shadow-accent: 0 0 0 1px rgba(47, 111, 237, 0.12), 0 4px 12px -2px rgba(47, 111, 237, 0.15);
  --ease: cubic-bezier(0.23, 1, 0.32, 1);
  /* aliases used by the car sketch and the report page */
  --ink: var(--text-1); --ink-2: var(--text-2); --muted: var(--text-3); --grid: var(--border); --axis: var(--border-strong);
  --page: var(--surface); --surface-3: var(--surface-2); --accent-2: var(--accent); --good: var(--success);
  --critical: var(--danger); --serious: #ea580c; --seq-track: #dbe6fb; --seq-fill: var(--accent);
  --glass-1: #e3ecfb; --glass-2: #c3d4f2; --car-body: #ffffff; --car-line: #1f2a44;
  --stage-1: #ffffff; --stage-2: #eef1f7; --radius: 12px; --shadow: var(--shadow-sm); --shadow-lift: var(--shadow-md);
  color-scheme: light;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: var(--bg); color: var(--text-1); font-size: 13px;
  line-height: 1.45; -webkit-font-smoothing: antialiased; }
[hidden] { display: none !important; }
h1, h2, h3, h4, p { margin: 0; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
:where(button, a, input, select, textarea):focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
::selection { background: rgb(37 99 235 / 0.12); }
.ico { flex: none; }
.muted { color: var(--text-2); }
.faint { color: var(--text-3); }
.small { font-size: 11.5px; }
.mono { font-family: ui-monospace, "Cascadia Mono", Consolas, monospace; }
.idcode { font-family: ui-monospace, "Cascadia Mono", Consolas, monospace; font-size: 11px; color: var(--text-3); }
.label { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.14em; color: var(--text-3); }
.num { font-variant-numeric: tabular-nums; }

/* ------------------------------------------------------------------ app shell */
#app { height: 100vh; display: grid; grid-template-rows: 56px minmax(0, 1fr); }
.topbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 0 24px;
  border-bottom: 1px solid var(--border); background: rgba(255, 255, 255, 0.9); backdrop-filter: blur(10px);
  box-shadow: 0 1px 8px rgba(0, 0, 0, 0.05); z-index: 10; }
.wordmark { display: flex; align-items: center; gap: 8px; font-weight: 600; font-size: 15px; letter-spacing: -0.01em; }
.wordmark svg { color: var(--accent); }
.nav { display: flex; gap: 4px; padding: 3px; background: var(--surface); border: 1px solid var(--border); border-radius: 999px; }
.nav button { border: 0; background: none; padding: 6px 14px; border-radius: 999px; font-size: 12px; font-weight: 600;
  color: var(--text-2); display: inline-flex; align-items: center; gap: 6px; transition: background 150ms, color 150ms; }
.nav button:hover { color: var(--text-1); }
.nav button[aria-selected="true"] { background: #fff; color: var(--accent); box-shadow: var(--shadow-sm); }
.who { display: flex; align-items: center; gap: 8px; }
.who input { width: 150px; border: 1px solid var(--border); border-radius: 999px; padding: 5px 12px; font-size: 12px; background: #fff; }
.pill-badge { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--border); background: #fff;
  border-radius: 999px; padding: 4px 10px; font-size: 11px; font-weight: 500; color: var(--text-2); box-shadow: var(--shadow-sm); }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: #34d399; animation: blink 1.6s ease-in-out infinite; }
@keyframes blink { 50% { opacity: 0.35; } }
.view { min-height: 0; overflow: hidden; display: flex; flex-direction: column; }

/* ------------------------------------------------------------------ primitives */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; border: 1px solid var(--border);
  background: #fff; border-radius: 999px; padding: 6px 14px; font-size: 12px; font-weight: 600; color: var(--text-2);
  transition: all 150ms var(--ease); white-space: nowrap; text-decoration: none; }
.btn:hover { border-color: var(--accent-border); background: var(--accent-soft); color: var(--accent); }
.btn:active { transform: scale(0.97); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn.primary:hover { filter: brightness(1.08); color: #fff; }
.btn.success { background: var(--success); border-color: var(--success); color: #fff; }
.btn.success:hover { filter: brightness(1.08); color: #fff; }
.btn.danger { color: var(--danger); }
.btn.danger:hover { background: var(--danger-soft); border-color: #fecaca; }
.btn:disabled { opacity: 0.5; pointer-events: none; }
.chip { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px; border-radius: 999px;
  border: 1px solid var(--border); background: var(--surface-2); font-size: 10.5px; font-weight: 600; color: var(--text-2); white-space: nowrap; }
.chip .dot { width: 6px; height: 6px; border-radius: 50%; }
.chip .chip-ico { display: none; }
.chip.lg { height: 24px; font-size: 11.5px; }
.tone-success { background: var(--success-soft); color: var(--success); border-color: #a7f3d0; }
.tone-warning { background: var(--warning-soft); color: var(--warning); border-color: #fde68a; }
.tone-danger { background: var(--danger-soft); color: var(--danger); border-color: #fecaca; }
.tone-accent { background: var(--accent-soft); color: var(--accent); border-color: var(--accent-border); }
.tone-neutral { background: var(--surface-2); color: var(--text-2); border-color: var(--border); }
.card { background: #fff; border: 1px solid var(--border); border-radius: 14px; box-shadow: var(--shadow-sm); min-width: 0; min-height: 0; }
.card-pad { padding: 14px 16px; }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 10px; }
.card-title { font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 7px; }
.sec-letter { display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; background: var(--accent-soft);
  color: var(--accent); font-size: 11px; font-weight: 700; }
.spinner { width: 14px; height: 14px; border-radius: 50%; border: 2px solid var(--accent-border); border-top-color: var(--accent); animation: spin 0.7s linear infinite; flex: none; }
@keyframes spin { to { transform: rotate(360deg); } }
.pending { display: flex; align-items: center; gap: 12px; padding: 18px; border-radius: 16px; border: 1px solid var(--border); background: var(--surface); }
.reveal { animation: reveal 0.5s var(--ease) both; }
.reveal-1 { animation-delay: 60ms; } .reveal-2 { animation-delay: 120ms; } .reveal-3 { animation-delay: 180ms; }
.reveal-4 { animation-delay: 240ms; } .reveal-5 { animation-delay: 300ms; }
@keyframes reveal { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
@keyframes slide-in { from { opacity: 0; transform: translateX(22px); } to { opacity: 1; transform: none; } }
.pulse-ring { animation: pulse-ring 1.8s var(--ease) infinite; }
@keyframes pulse-ring { 0% { box-shadow: 0 0 0 0 rgb(37 99 235 / 0.35); } 100% { box-shadow: 0 0 0 8px rgb(37 99 235 / 0); } }
.kbd { border: 1px solid var(--border); background: var(--surface); border-radius: 4px; padding: 1px 5px; font-size: 10px; font-family: ui-monospace, Consolas, monospace; color: var(--text-2); }
.swatch { width: 9px; height: 9px; border-radius: 50%; display: inline-block; flex: none; }
.key { display: inline-flex; align-items: center; gap: 5px; }
.legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 11px; color: var(--text-2); }
.toast { position: fixed; left: 50%; bottom: 64px; transform: translateX(-50%); background: var(--text-1); color: #fff;
  padding: 9px 16px; border-radius: 10px; font-size: 12px; z-index: 50; box-shadow: var(--shadow-md); animation: reveal 0.3s var(--ease) both; }
.tip { position: fixed; z-index: 60; max-width: 320px; background: var(--text-1); color: #fff; padding: 6px 9px; border-radius: 7px; font-size: 11px; pointer-events: none; }

/* ------------------------------------------------------------------ hero */
.hero { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 0 24px 40px;
  background: radial-gradient(ellipse 90% 55% at 50% 60%, rgba(47, 111, 237, 0.07) 0%, #ffffff 62%); }
.kicker { display: inline-flex; align-items: center; gap: 6px; border: 1px solid rgba(47, 111, 237, 0.25); background: rgba(47, 111, 237, 0.06);
  color: var(--accent); border-radius: 999px; padding: 4px 12px; font-size: 11px; font-weight: 600; letter-spacing: 0.1em; }
.hero h1 { margin-top: 18px; font-size: clamp(2.8rem, 6vw, 5.4rem); font-weight: 750; line-height: 0.92; letter-spacing: -0.045em; text-align: center; }
.hero .sub { margin-top: 14px; max-width: 540px; text-align: center; font-size: 15px; color: var(--text-3); }
.askbox { margin-top: 30px; width: min(720px, 100%); border: 1px solid var(--border); background: #fff; border-radius: 22px;
  box-shadow: 0 2px 20px rgba(0, 0, 0, 0.07); display: flex; align-items: center; gap: 12px; padding: 12px 12px 12px 20px; }
.askbox textarea { flex: 1; border: 0; outline: none; resize: none; font-size: 15px; line-height: 1.6; height: 26px; background: none; }
.send { width: 34px; height: 34px; border-radius: 10px; border: 0; background: var(--accent); color: #fff; display: grid; place-items: center; transition: all 150ms var(--ease); flex: none; }
.send:hover { filter: brightness(1.1); }
.send:active { transform: scale(0.94); }
.quick { margin-top: 14px; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 820px; }
.quick button { border: 1px solid var(--border); background: #fff; border-radius: 999px; padding: 6px 13px; font-size: 12px; font-weight: 500; color: var(--text-2); transition: all 150ms; }
.quick button:hover { border-color: var(--accent-border); background: var(--accent-soft); color: var(--accent); }
.hero-meta { margin-top: 24px; display: flex; align-items: center; gap: 12px; font-size: 11px; color: var(--text-3); flex-wrap: wrap; justify-content: center; }
.hero-meta .sep { width: 1px; height: 12px; background: var(--border); }

/* ------------------------------------------------------------------ work screen */
.work { flex: 1; min-height: 0; display: grid; grid-template-rows: 48px minmax(0, 1fr) 48px; background: var(--surface); }
.strip { display: flex; align-items: center; gap: 10px; padding: 0 24px; border-bottom: 1px solid var(--border); background: var(--surface); }
.strip .st { display: flex; align-items: center; gap: 10px; flex: 1; }
.strip .st:last-child { flex: none; }
.strip .st button { display: flex; align-items: center; gap: 7px; border: 0; background: none; padding: 4px 8px; border-radius: 8px;
  font-size: 12px; font-weight: 500; color: var(--text-3); white-space: nowrap; }
.strip .st.done button { color: var(--text-1); }
.strip .st.done button:hover, .strip .st.viewing button { background: #fff; box-shadow: var(--shadow-sm); }
.strip .st.active button { color: var(--accent); }
.strip .st.wait button { color: var(--warning); }
.strip .st.skipped button { color: var(--text-3); text-decoration: line-through; }
.sdot { width: 10px; height: 10px; border-radius: 50%; border: 1px solid var(--border-strong); background: var(--surface); flex: none; display: grid; place-items: center; }
.st.done .sdot { width: 16px; height: 16px; border: 0; background: var(--accent); color: #fff; }
.st.active .sdot { border: 0; background: var(--accent); }
.st.wait .sdot { border: 0; background: var(--warning); }
.sline { position: relative; flex: 1; height: 1px; background: var(--border); }
.sline::after { content: ""; position: absolute; inset: 0; background: var(--accent); transform: scaleX(0); transform-origin: left; transition: transform 0.45s var(--ease); }
.st.done .sline::after, .st.skipped .sline::after { transform: scaleX(1); }
.work-main { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 300px; }
.canvas { min-height: 0; overflow: hidden; padding: 18px 22px; position: relative; }
.panel { height: 100%; min-height: 0; display: grid; gap: 14px; animation: slide-in 0.45s var(--ease) both; }
.panel-title { display: flex; align-items: baseline; gap: 10px; }
.panel-title h2 { font-size: 17px; font-weight: 600; letter-spacing: -0.012em; }
.feed { min-height: 0; border-left: 1px solid var(--border); background: #fff; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.feed-head { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; border-bottom: 1px solid var(--border); }
.feed-list { min-height: 0; overflow: hidden; display: flex; flex-direction: column; justify-content: flex-end; gap: 4px; padding: 10px 12px; margin: 0; list-style: none; }
.feed-row { display: flex; gap: 9px; padding: 6px 8px; border-radius: 8px; border: 1px solid transparent; animation: feed-in 0.32s var(--ease) both; flex: none; }
.feed-row:hover { background: var(--surface); border-color: var(--border); }
.feed-row.wait { background: var(--warning-soft); border-color: #fde68a; }
@keyframes feed-in { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
.glyph { width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; font-size: 11px; font-weight: 700; flex: none; font-family: ui-monospace, Consolas, monospace; }
.feed-row .fw { font-size: 10.5px; font-weight: 600; display: flex; gap: 6px; }
.feed-row .t { font-size: 12px; color: var(--text-1); }
.feed-row .d { font-size: 10.5px; color: var(--text-2); font-family: ui-monospace, Consolas, monospace; display: -webkit-box; -webkit-line-clamp: 2; line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.feed-row .el { margin-left: auto; font-family: ui-monospace, Consolas, monospace; font-size: 10px; color: var(--text-3); font-weight: 400; }
.bottombar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0 24px; border-top: 1px solid var(--border); background: #fff; }
.linkbtn { border: 0; background: none; font-size: 12px; font-weight: 500; color: var(--text-3); }
.linkbtn:hover { color: var(--text-1); }
.status-txt { font-size: 12px; font-weight: 500; color: var(--text-3); display: flex; align-items: center; gap: 8px; }

/* ------------------------------------------------------------------ stage content */
.qline { font-size: 19px; font-weight: 600; letter-spacing: -0.01em; line-height: 1.5; }
.qline mark { background: none; border-bottom: 2px solid; padding: 0 1px; color: inherit; }
.mk-vehicle { border-color: var(--accent) !important; } .mk-market { border-color: var(--success) !important; }
.mk-feature { border-color: var(--warning) !important; } .mk-intent { border-color: #8b5cf6 !important; } .mk-powertrain { border-color: var(--info) !important; }
.slots { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; }
.slot { padding: 12px 14px; border-radius: 12px; border: 1px solid var(--border); background: #fff; position: relative; overflow: hidden; }
.slot::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--border-strong); }
.slot.ok::before { background: var(--accent); } .slot.missing::before { background: var(--warning); }
.slot.missing { background: var(--warning-soft); border-color: #fde68a; }
.slot .v { font-size: 14px; font-weight: 600; margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.slot .s { font-size: 10.5px; color: var(--text-3); margin-top: 3px; display: -webkit-box; -webkit-line-clamp: 2; line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.optgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 10px; }
.opt { text-align: left; border: 1px solid var(--border); background: #fff; border-radius: 14px; padding: 12px; display: flex; flex-direction: column; gap: 6px;
  transition: all 180ms var(--ease); box-shadow: var(--shadow-sm); }
.opt:hover { border-color: var(--accent-border); box-shadow: var(--shadow-accent); transform: translateY(-2px); }
.opt b { font-size: 13px; }
.opt .car-mini { height: 56px; }
.opt .car-mini svg { width: 100%; height: 100%; }
.scorebar { height: 5px; border-radius: 3px; background: var(--surface-2); overflow: hidden; }
.scorebar span { display: block; height: 100%; background: var(--accent); border-radius: 3px; width: 0; transition: width 0.8s var(--ease); }
.crumb { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 12px; }
.crumb .lvl { display: inline-flex; flex-direction: column; padding: 6px 10px; border-radius: 10px; background: #fff; border: 1px solid var(--border); }
.crumb .lvl small { font-size: 9.5px; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.1em; font-weight: 600; }
.crumb .arr { color: var(--text-3); }
.funnel { display: flex; flex-direction: column; gap: 10px; }
.frow { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 14px; align-items: center; }
.frow .fl b { display: block; font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }
.frow .fl span { font-size: 11.5px; color: var(--text-2); }
.fbar-wrap { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.fbar { height: 22px; border-radius: 0 6px 6px 0; background: var(--accent); width: 0; min-width: 4px; transition: width 0.9s var(--ease); }
.frow:nth-child(1) .fbar { background: #c7d7fa; } .frow:nth-child(2) .fbar { background: #93b2f5; } .frow:nth-child(3) .fbar { background: #5a8cf0; }
.frule { font-size: 10.5px; color: var(--text-3); font-family: ui-monospace, Consolas, monospace; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.stack { display: flex; gap: 2px; height: 14px; border-radius: 0 4px 4px 0; overflow: hidden; }
.stack span { height: 100%; transition: flex-grow 0.6s var(--ease); }
.tree { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; min-height: 0; }
.tcol { display: flex; flex-direction: column; gap: 6px; min-height: 0; overflow: hidden; }
.tnode { padding: 7px 10px; border-radius: 10px; border: 1px solid var(--border); background: #fff; display: flex; justify-content: space-between; gap: 8px; align-items: center; font-size: 12px; transition: all 150ms; flex: none; }
.tnode.sel { border-color: var(--accent-border); background: var(--accent-soft); }
button.tnode { width: 100%; text-align: left; }
button.tnode:hover { border-color: var(--accent-border); }
.tnode .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: flex; align-items: center; gap: 6px; }
.tnode .n { font-variant-numeric: tabular-nums; color: var(--text-2); font-weight: 600; flex: none; }
.review { padding: 12px 14px; border-radius: 12px; border: 1px solid var(--border); background: #fff; display: flex; flex-direction: column; gap: 7px; min-height: 0; overflow: hidden; }
.review .txt { font-size: 11.5px; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 3; line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.aspect { display: grid; grid-template-columns: 1fr auto; gap: 3px 8px; padding: 6px 9px; border-radius: 9px; background: var(--surface); font-size: 11px; }
.aspect.hit { background: var(--accent-soft); }
