              {features.length > 1 && (
                <div className="tabs" role="tablist" aria-label="Features">
                  {features.map((f, i) => (
                    <button key={f.feature} className="tab" role="tab" aria-selected={i === featIdx} onClick={() => {
                      setFeatIdx(i);
