              )}
              {features.map((f) => (
                <DecisionForm key={f.feature} result={evaluation.result} feature={f} />
              ))}
              {!fr && <p className="small muted">Select a related feature in step 1 to record a decision against the evidence.</p>}
            </div>
          </section>
        </>
      )}
    </>
  );
}

