import type { AgentEvaluation, AgentStatus, Explained, InterpretResult } from "../types";

export type Phase = "idle" | "interpreting" | "review" | "evaluating" | "done";
export type ExplainState = "idle" | "running" | "done" | "unavailable" | "error" | "stale";
type StepState = "waiting" | "running" | "done" | "off" | "error";

const STATE_TEXT: Record<StepState, string> = { waiting: "Waiting", running: "Working", done: "Done", off: "Not available", error: "Failed" };

/** The pipeline as four steps: three agents around the deterministic decision engine. */
export default function AgentSteps({
  status,
  phase,
  interp,
  evaluation,
  explainState,
  explained,
}: {
  status: AgentStatus | null;
  phase: Phase;
  interp: InterpretResult | null;
  evaluation: AgentEvaluation | null;
  explainState: ExplainState;
  explained: Explained | null;
}) {
  const m = status?.models ?? {};
  const llm = Boolean(status?.llm_configured);
  const agentState = (): StepState =>
    explainState === "running" ? "running" : explainState === "done" ? "done" : explainState === "unavailable" ? "off"
      : explainState === "error" ? "error" : "waiting";
  const steps: { n: string; title: string; who: string; what: string; state: StepState; result?: string }[] = [
    {
      n: "01",
      title: "Retriever agent",
      who: llm ? m.retriever : "rules (no API key)",
      what: "Matches the idea to features in the knowledge graph and validates the result.",
      state: phase === "interpreting" ? "running" : interp ? "done" : "waiting",
      result: interp ? `${interp.spec.features.length} feature(s), ${interp.candidates.length} candidates` : undefined,
    },
    {
      n: "02",
      title: "Decision engine",
      who: "deterministic, no LLM",
      what: "Computes every number from the processed data and model outputs and cites graph nodes.",
      state: phase === "evaluating" ? "running" : evaluation ? "done" : "waiting",
      result: evaluation ? `${evaluation.facts.length} facts` : undefined,
    },
    {
      n: "03",
      title: "Explainer agent",
      who: explained ? explained.explanation.model : llm ? m.explainer : "needs an OpenAI key",
      what: "Writes the brief for product management. Every claim cites fact IDs.",
      state: agentState(),
      result: explained ? `${explained.verification.claims.length} claims, ${explained.explanation.attempts} draft(s)` : undefined,
    },
    {
      n: "04",
      title: "Verifier agent",
      who: explained ? `rules + ${explained.verification.semantic_model}` : llm ? `rules + ${m.verifier}` : "needs an OpenAI key",
      what: "Checks numbers, labels, quotes and scope, then entailment. Failures are rewritten once, then removed.",
      state: agentState(),
      result: explained ? `${explained.verification.n_verified} verified, ${explained.verification.n_removed} removed` : undefined,
    },
  ];
  return (
    <ol className="steps" aria-label="Evaluation pipeline">
      {steps.map((s) => (
        <li key={s.n} className={`step step--${s.state}`}>
          <div className="spread">
            <span className="step__n">{s.n}</span>
            <span className="step__state">
              <span className="step__dot" aria-hidden />
              {STATE_TEXT[s.state]}
            </span>
          </div>
          <p className="step__title">{s.title}</p>
          <p className="caption">{s.who}</p>
          <p className="small step__what">{s.what}</p>
          {s.result && <p className="small step__result">{s.result}</p>}
        </li>
      ))}
    </ol>
  );
}

