/* ------------------------------------------------------------------ layout */
.wrap { max-width: var(--max); margin: 0 auto; padding: 0 var(--gutter); }
.band { padding: var(--s-8) 0; }
.band--soft { background: var(--surface-background-secondary); }
.band--tight { padding: var(--s-7) 0; }
.stack > * + * { margin-top: var(--s-4); }
.stack-lg > * + * { margin-top: var(--s-6); }
.row { display: flex; gap: var(--s-4); align-items: center; flex-wrap: wrap; }
.spread { display: flex; justify-content: space-between; gap: var(--s-4); align-items: baseline; flex-wrap: wrap; }
.lead { font-size: var(--fs-lead); line-height: 28px; max-width: 72ch; }
.muted { color: var(--disclaimer); }
.small { font-size: var(--fs-small); }
.caption, .disclaimer { font-size: var(--fs-label); line-height: 18px; font-weight: var(--w-default); color: var(--disclaimer); }
.measure { max-width: 72ch; }
.eyebrow { font-size: var(--fs-label); font-weight: var(--w-clickable); letter-spacing: 0.6px; text-transform: uppercase; color: var(--disclaimer); }
.section-title { font-size: var(--fs-section); line-height: 50px; font-weight: var(--w-default); }

/* ------------------------------------------------------------------ buttons (bmw.de cmp-button: 52px, 3px, 15px/500) */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s-2);
  min-height: 52px; padding: 4px 24px; border: 0; border-radius: var(--radius-control); cursor: pointer;
  font-size: var(--fs-ui); font-weight: var(--w-clickable); line-height: 24px; text-decoration: none; white-space: nowrap;
  background: var(--cta); color: #fff; transition: background-color 0.15s ease;
}
.btn:hover { background: var(--cta-hover); }
.btn:disabled { background: var(--cta-disabled); color: #fff; cursor: not-allowed; }
.btn--secondary, .btn--dark { background: var(--nba); color: #fff; }
.btn--secondary:hover, .btn--dark:hover { background: var(--nba-hover); }
.btn--secondary:disabled, .btn--dark:disabled { background: var(--nba-disabled); }
.btn--outline { background: transparent; color: var(--heading); box-shadow: inset 0 0 0 1px var(--heading); }
.btn--outline:hover { background: transparent; box-shadow: inset 0 0 0 2px var(--heading); }
.btn--on-dark { background: transparent; color: #f2f2f2; box-shadow: inset 0 0 0 1px #f2f2f2; }
.btn--on-dark:hover { background: transparent; box-shadow: inset 0 0 0 2px #fff; }
.btn--small { min-height: 40px; padding: 4px 16px; font-size: var(--fs-small); }
.textlink {
  background: none; border: 0; padding: 0; cursor: pointer; color: var(--heading); display: inline-flex; align-items: center; gap: 6px;
  font-size: var(--fs-ui); font-weight: var(--w-clickable); text-decoration: none;
}
.textlink::after { content: ""; width: 7px; height: 7px; border-right: 1.5px solid currentColor; border-top: 1.5px solid currentColor; transform: rotate(45deg); }
.textlink:hover { color: var(--cta); }

/* ------------------------------------------------------------------ inputs (bmw.de: #8e8e8e border, 400 weight) */
.field { display: flex; flex-direction: column; gap: var(--s-2); }
.field label, .label { font-size: var(--fs-small); font-weight: var(--w-input); color: var(--copy-text); }
.input, .select, .textarea {
  min-height: 52px; padding: 12px 16px; border: 1px solid var(--input-border-color); border-radius: var(--radius-control);
  background: #fff; color: var(--copy-text); font-weight: var(--w-input); width: 100%;
}
.input:hover, .select:hover, .textarea:hover { border-color: var(--input-border-color-hover); }
.input:focus, .select:focus, .textarea:focus { outline: none; border-color: var(--input-border-color-hover); box-shadow: inset 0 0 0 2px var(--cta); }
.input::placeholder, .textarea::placeholder { color: var(--disclaimer); font-weight: var(--w-default); }
.textarea { min-height: 104px; resize: vertical; line-height: 1.5; }
.select { appearance: none; padding-right: 44px; background-image: linear-gradient(45deg, transparent 50%, var(--heading) 50%), linear-gradient(135deg, var(--heading) 50%, transparent 50%); background-position: calc(100% - 22px) 23px, calc(100% - 16px) 23px; background-size: 6px 6px; background-repeat: no-repeat; }
.check { display: flex; gap: 10px; align-items: flex-start; font-size: var(--fs-small); cursor: pointer; }
.check input { width: 18px; height: 18px; margin-top: 2px; accent-color: var(--cta); flex: none; }

/* ------------------------------------------------------------------ filter tags (bmw.de --filtertag-*) */
.chips { display: flex; gap: var(--s-2); flex-wrap: wrap; }
.chip {
  display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 6px 14px;
  border: 1px solid var(--filtertag); border-radius: var(--radius-control); background: #fff; color: var(--disclaimer);
  font-size: var(--fs-small); font-weight: var(--w-input); cursor: pointer;
}
.chip:hover { border-color: var(--heading); color: var(--heading); }
.chip[aria-pressed="true"] { background: var(--filtertag-selected); border-color: var(--filtertag-selected); color: #fff; }
.chip:disabled { background: var(--neutral-background); color: #bbb; border-color: var(--neutral-background); cursor: not-allowed; }

/* ------------------------------------------------------------------ tabs (bmw.de content navigation) */
.tabs { display: flex; gap: var(--s-5); border-bottom: 1px solid var(--border); overflow-x: auto; scrollbar-width: none; }
.tab {
  background: none; border: 0; padding: 14px 0 12px; cursor: pointer; white-space: nowrap; position: relative;
  font-size: var(--fs-ui); font-weight: var(--w-input); color: var(--disclaimer);
}
.tab:hover { color: var(--heading); }
.tab[aria-selected="true"] { color: var(--heading); }
.tab[aria-selected="true"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 3px; background: var(--heading); }

/* ------------------------------------------------------------------ cards and tiles (rounded by product choice) */
.card { background: #fff; border: 1px solid var(--border); border-radius: var(--radius-card); padding: var(--s-5); }
.card--soft { background: var(--surface-background-secondary); border-color: transparent; }
.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: var(--s-3); }
.tile {
  text-align: left; background: #fff; border: 1px solid var(--border); border-radius: var(--radius-tile); padding: 16px 20px; cursor: pointer;
  display: flex; flex-direction: column; gap: var(--s-1); color: var(--copy-text); transition: border-color 0.15s ease;
}
.tile:hover { border-color: var(--input-border-color); }
.tile[aria-pressed="true"] { border-color: var(--cta); box-shadow: inset 0 0 0 1px var(--cta); }
.tile__title { font-weight: var(--w-clickable); color: var(--heading); font-size: var(--fs-sub2); line-height: 1.3; }

/* ------------------------------------------------------------------ key figures (bmw.de cmp-technicaldatafact) */
.facts-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: var(--s-5) var(--s-6); }
.techfact__label { font-size: var(--fs-sub2); line-height: 30px; color: var(--copy-text); font-weight: var(--w-default); }
.techfact__value { font-size: var(--fs-h3); line-height: 38px; color: var(--heading); font-weight: var(--w-default); }
.specs { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: var(--s-3); }
.spec { padding: var(--s-5); border-radius: var(--radius-tile); background: var(--surface-background-secondary); }
.spec__value { font-size: var(--fs-h3); line-height: 1.4; color: var(--heading); }
.spec__label { font-size: var(--fs-small); color: var(--disclaimer); }

/* ------------------------------------------------------------------ tables */
.table-scroll { overflow-x: auto; }
.table th, .table td { padding: 12px 16px 12px 0; text-align: left; border-bottom: 1px solid var(--border); vertical-align: top; font-size: var(--fs-small); }
.table th { font-weight: var(--w-input); color: var(--disclaimer); font-size: var(--fs-label); white-space: nowrap; }
.table td.r, .table th.r { text-align: right; }

/* ------------------------------------------------------------------ markers */
.verdict { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-small); font-weight: var(--w-input); color: var(--heading); white-space: nowrap; }
.verdict__mark { width: 10px; height: 10px; flex: none; border-radius: 50%; }
.rec { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-small); font-weight: var(--w-clickable); color: var(--heading); white-space: nowrap; }
.rec__mark { width: 12px; height: 12px; flex: none; border: 2px solid var(--cta); border-radius: 2px; }
.rec--prioritise .rec__mark { background: var(--cta); }
.rec--consider .rec__mark { background: var(--information-background); }
.rec--low .rec__mark { border-color: var(--muted-soft); background: var(--surface-strong); }
.rec--insufficient .rec__mark { border: 2px dashed var(--muted-soft); }
.rec--notsold .rec__mark { border: 2px solid var(--border); }
.rec--insufficient, .rec--notsold { font-weight: var(--w-input); color: var(--disclaimer); }
.fit { font-size: 15px; line-height: 1; }

/* ------------------------------------------------------------------ notifications (bmw.de status pairs) */
.note { border-radius: var(--radius-tile); padding: var(--s-4) var(--s-5); font-size: var(--fs-small); background: var(--neutral-background); color: var(--copy-text); }
.note--info { background: var(--information-background); }
.note--warn { background: var(--warning-background); }
.note--error { background: var(--error-background); }
.note--success { background: var(--success-background); }
.note strong { font-weight: var(--w-clickable); }
.state { padding: var(--s-6) 0; color: var(--disclaimer); }
.error { color: var(--error); font-weight: var(--w-input); }
.skeleton { background: linear-gradient(90deg, #f2f2f2, #e6e6e6, #f2f2f2); background-size: 200% 100%; animation: shimmer 1.4s infinite; height: 16px; margin: 10px 0; border-radius: 3px; }
@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
details > summary { cursor: pointer; font-size: var(--fs-small); color: var(--heading); font-weight: var(--w-clickable); }
details > summary:hover { color: var(--cta); }
.quote { border-left: 2px solid var(--border); padding-left: var(--s-4); font-size: var(--fs-small); }
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 4px 16px; font-size: var(--fs-small); margin: 0; }
.kv dt { color: var(--disclaimer); }
.kv dd { margin: 0; color: var(--heading); word-break: break-word; }
/* ------------------------------------------------------------------ global navigation over the stage (bmw.de) */
.nav { position: absolute; top: 0; left: 0; right: 0; z-index: 10; height: var(--nav-h); color: #fff; }
.nav__inner { height: 100%; display: flex; align-items: center; gap: var(--s-5); border-bottom: 1px solid rgba(255, 255, 255, 0.75); }
.brand { display: flex; align-items: center; gap: var(--s-4); text-decoration: none; color: #fff; white-space: nowrap; }
.brand__logo { width: 52px; height: 52px; display: block; }
.brand__wordmark { font-weight: var(--w-price); font-size: 22px; letter-spacing: 1px; }
.brand__name { font-size: var(--fs-ui); font-weight: var(--w-clickable); }
.nav__status { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; font-size: var(--fs-label); font-weight: var(--w-input); color: #e6e6e6; white-space: nowrap; }
.nav__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--warning); }
.nav__status--ok .nav__dot { background: var(--success); }
@media (max-width: 767px) { .nav__status { display: none; } .brand__logo { width: 40px; height: 40px; } }

/* ------------------------------------------------------------------ stage (hero) */
.stage { background: radial-gradient(120% 140% at 85% 20%, #2b3440 0%, #11161c 45%, var(--stage) 75%); color: #fff; }
.stage__inner { padding-top: calc(var(--nav-h) + 96px); padding-bottom: 72px; }
.stage__title { color: #fff; font-size: var(--fs-stage); line-height: 50px; font-weight: var(--w-clickable); text-transform: uppercase; max-width: 22ch; }
.stage__sub { margin-top: var(--s-5); font-size: var(--fs-stage-sub); line-height: 24px; font-weight: var(--w-clickable); text-transform: uppercase; }
.stage__copy { margin-top: var(--s-5); font-size: var(--fs-lead); line-height: 28px; max-width: 64ch; color: #f2f2f2; }
.stage__form { display: flex; gap: var(--s-4); margin-top: var(--s-6); max-width: 1000px; }
.stage__input { min-height: 56px; font-size: var(--fs-sub2); border-color: #fff; }
.stage__cta { min-height: 56px; padding: 4px 32px; }
.stage__examples { margin-top: var(--s-5); display: flex; flex-direction: column; gap: var(--s-2); }
.stage__examples-label { font-size: var(--fs-label); font-weight: var(--w-clickable); text-transform: uppercase; letter-spacing: 0.6px; color: #bbb; }
.chip--on-dark { background: transparent; color: #e6e6e6; border-color: #8e8e8e; }
.chip--on-dark:hover { border-color: #fff; color: #fff; }
.chip--on-dark:disabled { background: transparent; color: #666; border-color: #4d4d4d; }
@media (max-width: 767px) {
  .stage__title { line-height: 1.15; }
  .stage__form { flex-direction: column; }
  .stage__inner { padding-top: calc(var(--nav-h) + 48px); padding-bottom: 48px; }
}
.sourceline { padding: var(--s-4) 0; border-bottom: 1px solid var(--border); }

/* ------------------------------------------------------------------ pipeline steps */
.steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--s-3); }
@media (max-width: 1024px) { .steps { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) { .steps { grid-template-columns: 1fr; } }
.step { background: var(--surface-background-secondary); border-radius: var(--radius-card); padding: var(--s-5); display: flex; flex-direction: column; gap: 6px; }
.step__n { font-size: var(--fs-label); font-weight: var(--w-clickable); color: var(--disclaimer); letter-spacing: 0.6px; }
.step__state { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-label); font-weight: var(--w-input); color: var(--disclaimer); }
.step__dot { width: 8px; height: 8px; border-radius: 50%; background: #bbb; }
.step--running .step__dot { background: var(--cta); animation: pulse 1s ease-in-out infinite; }
.step--done .step__dot { background: var(--success); }
.step--off .step__dot { background: var(--warning); }
.step--error .step__dot { background: var(--error); }
.step__title { font-size: var(--fs-sub1); font-weight: var(--w-input); color: var(--heading); margin-top: 4px; }
.step__what { color: var(--copy-text); }
.step__result { margin-top: auto; padding-top: var(--s-2); font-weight: var(--w-clickable); color: var(--heading); }
@keyframes pulse { 50% { opacity: 0.3; } }

/* ------------------------------------------------------------------ step 1 review */
.review__group { border: 0; margin-left: 0; margin-right: 0; margin-bottom: 0; padding: 0; min-width: 0; display: flex; flex-direction: column; gap: var(--s-3); }
.review__legend { font-size: var(--fs-sub1); color: var(--heading); font-weight: var(--w-input); margin-bottom: var(--s-3); padding: 0; }
.review__legend .caption { margin-left: 8px; }
.review__grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-5) var(--s-6); }
@media (max-width: 900px) { .review__grid { grid-template-columns: 1fr; } }
.tile:disabled { opacity: 0.45; cursor: not-allowed; }
.tile--static { cursor: default; }
.tile__check { width: 20px; height: 20px; border-radius: 50%; background: var(--cta); flex: none; position: relative; }
.tile__check::after { content: ""; position: absolute; left: 7px; top: 4px; width: 5px; height: 9px; border: solid #fff; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.tile__methods { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.method { font-size: 11px; font-weight: var(--w-input); color: var(--disclaimer); background: var(--neutral-background); border-radius: var(--radius-control); padding: 2px 6px; }
.bullets { margin: 6px 0 0; padding-left: 18px; }
.bullets li + li { margin-top: 4px; }

/* ------------------------------------------------------------------ in-page content navigation (bmw.de cmp-contentnavigation) */
.contentnav { position: sticky; top: 0; z-index: 20; background: #fff; border-bottom: 1px solid var(--border); }
.contentnav__inner { display: flex; align-items: center; gap: var(--s-5); min-height: 82px; }
.contentnav__tabs { display: flex; gap: var(--s-5); overflow-x: auto; scrollbar-width: none; flex: 1; align-self: stretch; }
.contentnav__tab { display: flex; align-items: center; position: relative; white-space: nowrap; text-decoration: none; font-size: var(--fs-ui); color: var(--disclaimer); font-weight: var(--w-input); }
.contentnav__tab:hover { color: var(--heading); }
.contentnav__tab[aria-current="true"] { color: var(--heading); }
.contentnav__tab[aria-current="true"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: var(--heading); }
@media (max-width: 767px) { .contentnav__cta { display: none; } .contentnav__inner { min-height: 60px; } }
.anchor { scroll-margin-top: 90px; }

/* ------------------------------------------------------------------ key figures */
.keyfigs { padding: var(--s-5) 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.keyfigs .verdict { font-size: var(--fs-h3); font-weight: var(--w-default); gap: 10px; }
.keyfigs .verdict__mark { width: 14px; height: 14px; }

/* ------------------------------------------------------------------ explanation */
.explain { display: flex; flex-direction: column; gap: var(--s-6); }
.explain__headline .claim__text { font-size: var(--fs-h2); line-height: 1.4; color: var(--heading); font-weight: var(--w-default); max-width: 60ch; }
.explain__grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-4); }
@media (max-width: 900px) { .explain__grid { grid-template-columns: 1fr; } }
.explain__card { background: #fff; border-color: transparent; }
.explain__title { font-size: var(--fs-sub1); line-height: 1.4; font-weight: var(--w-input); margin-bottom: var(--s-3); }
.claims { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--s-3); }
.claim { display: grid; grid-template-columns: 18px 1fr; gap: 10px; align-items: start; }
.claim__ok { width: 18px; height: 18px; border-radius: 50%; background: var(--success); margin-top: 3px; position: relative; }
.claim__ok::after { content: ""; position: absolute; left: 6px; top: 3px; width: 4px; height: 8px; border: solid #fff; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.claim__text { font-size: var(--fs-body); line-height: 1.55; }
.cite { position: relative; display: inline-block; vertical-align: 2px; margin-left: 2px; }
.cite__btn { min-width: 20px; height: 20px; padding: 0 6px; border: 0; border-radius: 10px; background: var(--information-background); color: var(--cta); font-size: 11px; font-weight: var(--w-clickable); line-height: 20px; cursor: pointer; }
.cite__btn:hover, .cite__btn[aria-expanded="true"] { background: var(--cta); color: #fff; }
.popover {
  position: absolute; z-index: 40; top: calc(100% + 8px); left: -8px; width: min(380px, 80vw);
  display: flex; flex-direction: column; gap: 8px; padding: 16px; background: #fff; border-radius: var(--radius-float); box-shadow: var(--shadow-float);
  font-size: var(--fs-small); line-height: 1.45; font-weight: var(--w-default); color: var(--copy-text); text-align: left; white-space: normal;
}
.popover__id { font-size: 11px; font-weight: var(--w-clickable); color: var(--disclaimer); font-variant-numeric: tabular-nums; word-break: break-all; }
.popover__src { font-size: var(--fs-label); color: var(--disclaimer); word-break: break-word; }
.popover__link { font-size: var(--fs-small); align-self: flex-start; }

/* ------------------------------------------------------------------ knowledge graph */
.graph { border: 1px solid var(--border); border-radius: var(--radius-card); overflow: hidden; background: #fff; }
.graph__bar { display: flex; justify-content: space-between; align-items: flex-end; gap: var(--s-4); flex-wrap: wrap; padding: 0 var(--s-5); border-bottom: 1px solid var(--border); }
.graph__tabs { border-bottom: 0; }
.legend { list-style: none; margin: 0; padding: 12px 0; display: flex; flex-wrap: wrap; gap: 6px 14px; font-size: var(--fs-label); color: var(--disclaimer); }
.legend li { display: inline-flex; align-items: center; gap: 6px; }
.legend__swatch { width: 10px; height: 10px; border-radius: 50%; }
.legend__swatch--cited { background: #fff; box-shadow: inset 0 0 0 3px var(--cta); width: 12px; height: 12px; }
.graph__body { display: grid; grid-template-columns: minmax(0, 1fr) 380px; min-height: 720px; }
.graph__canvas { height: 720px; background: #fff; }
.graph__inspector { border-left: 1px solid var(--border); padding: var(--s-5); overflow-y: auto; max-height: 720px; background: var(--surface-background-secondary); }
@media (max-width: 1024px) {
  .graph__body { grid-template-columns: 1fr; }
  .graph__canvas { height: 480px; }
  .graph__inspector { border-left: 0; border-top: 1px solid var(--border); max-height: none; }
}
.inspector__title { font-size: var(--fs-sub1); line-height: 1.35; word-break: break-word; }
.chip--small { min-height: 28px; padding: 2px 10px; font-size: var(--fs-label); }
.rels { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }

/* ------------------------------------------------------------------ verification */
.verify th.verify__rule, .verify td.verify__cell { text-align: center; padding-right: 8px; padding-left: 8px; }
.verify__text { font-size: var(--fs-small); color: var(--heading); max-width: 60ch; }
.verify__removed .verify__text { text-decoration: line-through; color: var(--disclaimer); }
.pill { display: inline-block; padding: 2px 10px; border-radius: 12px; font-size: var(--fs-label); font-weight: var(--w-clickable); white-space: nowrap; }
.pill--success { background: var(--success-background); color: #1f6e0a; }
.pill--error { background: var(--error-background); color: var(--error); }
.tick, .cross { display: inline-block; width: 18px; height: 18px; border-radius: 50%; position: relative; }
.tick { background: var(--success); }
.tick::after { content: ""; position: absolute; left: 6px; top: 3px; width: 4px; height: 8px; border: solid #fff; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.cross { background: var(--error); }
.cross::before, .cross::after { content: ""; position: absolute; left: 8px; top: 4px; width: 2px; height: 10px; background: #fff; }
.cross::before { transform: rotate(45deg); }
.cross::after { transform: rotate(-45deg); }

/* ------------------------------------------------------------------ series x market matrix + evidence panel */
.decision-grid { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: var(--s-6); align-items: start; }
@media (max-width: 1180px) { .decision-grid { grid-template-columns: 1fr; } }
.matrix { display: grid; gap: var(--s-2); overflow-x: auto; }
.matrix__row { display: contents; }
.matrix__corner { min-height: 1px; }
