/* Workspace: process flowchart + report on the left, a side panel that follows the current step on the right. */

/* ------------------------------------------------------------------ workspace */
.ws { --side-w: clamp(320px, 27vw, 410px); display: grid; grid-template-columns: minmax(0, 1fr) var(--side-w); gap: 24px;
  max-width: 1720px; margin: 0 auto; padding: 20px 24px 40px; align-items: start; }
.ws__main { min-width: 0; display: flex; flex-direction: column; gap: 18px; }
.ws__report { background: #fff; border: 1px solid var(--border); border-radius: var(--radius-card); box-shadow: var(--shadow-sm); padding: 18px 22px 24px; }
@media (max-width: 1024px) {
  .ws { grid-template-columns: 1fr; padding: 16px; }
  .ws__side { position: static !important; max-height: none !important; }
