.side__answer { font-size: var(--fs-body); line-height: 1.5; color: var(--heading); font-weight: 500; }
.side__groups { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.side__group { display: flex; justify-content: space-between; padding: 7px 10px; border-radius: 8px; font-weight: 500; }

/* components hosted in the narrow side panel */
.side .tiles { grid-template-columns: 1fr; }
.side .tile { padding: 10px 12px; }
.side .tile__title { font-size: 14px; }
.side .review__grid, .side .decision-form__grid, .side .policy__grid { grid-template-columns: 1fr; gap: 16px; }
