.flow__status { font-size: var(--fs-label); color: var(--disclaimer); font-variant-numeric: tabular-nums; }

.flow__scroll { overflow-x: auto; padding: 4px 2px 8px; margin: 0 -2px; }
.flow__lane { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(6, minmax(124px, 1fr)); column-gap: 26px; min-width: min-content; }
.fcol { position: relative; display: flex; flex-direction: column; gap: 6px; min-width: 0; }

/* step card */
.fnode { width: 100%; text-align: left; font: inherit; color: inherit; cursor: pointer; display: flex; flex-direction: column; gap: 3px; padding: 10px 11px;
  background: #fff; border: 1px solid var(--border); border-radius: 12px; box-shadow: var(--shadow-sm); min-height: 118px;
  transition: border-color 0.25s var(--ease), box-shadow 0.25s var(--ease), background-color 0.25s; }
