.fnode__icon { width: 24px; height: 24px; border-radius: 7px; display: grid; place-items: center; flex: none; background: var(--surface-background-secondary); color: var(--text-2); }
.fnode--retriever .fnode__icon, .fnode--brief .fnode__icon { background: var(--cta-soft); color: var(--cta); }
.fnode--you .fnode__icon { background: var(--success-background); color: var(--success); }
.fnode--engine .fnode__icon { background: var(--neutral-background); color: var(--heading); }
.fnode--explainer .fnode__icon { background: var(--violet-background); color: var(--violet); }
.fnode--verifier .fnode__icon { background: var(--warning-background); color: var(--warning); }
.fnode__state { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 500; color: var(--disclaimer); white-space: nowrap; }
.fnode__dot { width: 7px; height: 7px; border-radius: 50%; background: var(--input-border-color); flex: none; }
.spinner--sm { width: 10px; height: 10px; border-width: 2px; }
.fnode__title { font-size: 13.5px; font-weight: var(--w-clickable); color: var(--heading); line-height: 1.25; }
.fnode__sum { font-size: 12px; line-height: 1.35; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 3; line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.fnode__time { margin-top: auto; padding-top: 4px; font-size: 11.5px; font-weight: var(--w-clickable); color: var(--heading); }

.fnode--waiting { background: var(--surface-background-secondary); border-style: dashed; border-color: var(--input-border-color); box-shadow: none; }
.fnode--waiting .fnode__title, .fnode--waiting .fnode__sum { color: var(--disclaimer); }
.fnode--waiting .fnode__icon { background: #fff; color: var(--muted-soft); }
.fnode--running { border-color: var(--cta); box-shadow: var(--shadow-accent); }
.fnode--running .fnode__state { color: var(--cta); }
.fnode--wait { border-color: var(--warning); background: var(--warning-background); box-shadow: 0 0 0 3px rgba(217, 119, 6, 0.12); }
.fnode--wait .fnode__state { color: var(--warning); }
.fnode--wait .fnode__dot { background: var(--warning); animation: ring-warn 1.6s ease-out infinite; }
.fnode--done .fnode__dot { background: var(--success); }
.fnode--done .fnode__state { color: var(--success); }
.fnode--off { background: var(--surface-background-secondary); }
.fnode--off .fnode__dot, .fnode--stale .fnode__dot { background: var(--warning); }
.fnode--error { border-color: var(--error); }
.fnode--error .fnode__dot { background: var(--error); }
.fnode--error .fnode__state { color: var(--error); }
.fnode--stale { border-style: dashed; border-color: var(--warning); }
.fnode--stale .fnode__state { color: var(--warning); }
@keyframes ring-warn { 0% { box-shadow: 0 0 0 0 rgba(217, 119, 6, 0.45); } 100% { box-shadow: 0 0 0 7px rgba(217, 119, 6, 0); } }

/* arrow to the next column, level with the step cards */
.fedge { position: absolute; top: 48px; right: -26px; width: 26px; height: 16px; display: flex; align-items: center; justify-content: center; pointer-events: none; }
.fedge svg { width: 22px; height: 14px; overflow: visible; }
.fedge line, .fedge path { fill: none; stroke: var(--input-border-color); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.fedge--idle line { stroke-dasharray: 3 4; }
.fedge--done line, .fedge--done path, .fedge--active line, .fedge--active path { stroke: var(--cta); }
.fedge--active line { stroke-dasharray: 5 4; animation: flow-dash 0.6s linear infinite; }
@keyframes flow-dash { to { stroke-dashoffset: -9; } }

/* child nodes: what the step returned, added when its response arrives */
.fkids { list-style: none; margin: 0; padding: 4px 0 0 10px; display: flex; flex-direction: column; gap: 5px; position: relative; }
.fkids::before { content: ""; position: absolute; left: 3px; top: 0; bottom: 14px; border-left: 1.5px dashed var(--input-border-color); }
.fkids > li { position: relative; animation: kid-in 0.35s var(--ease) both; }
.fkids > li::before { content: ""; position: absolute; left: -7px; top: 14px; width: 7px; border-top: 1.5px dashed var(--input-border-color); }
@keyframes kid-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
.fkid { width: 100%; text-align: left; font: inherit; cursor: pointer; display: flex; flex-direction: column; gap: 1px; padding: 5px 8px;
  border-radius: 8px; border: 1px solid var(--border); background: #fff; border-left-width: 3px; transition: background-color 0.15s, border-color 0.15s; }
.fkid:hover { background: var(--cta-soft); border-color: var(--cta-border); }
.fkid[aria-expanded="true"] { background: var(--cta-soft); border-color: var(--cta); }
.fkid--ok { border-left-color: var(--success); }
.fkid--warn { border-left-color: var(--warning); }
.fkid--fail { border-left-color: var(--error); }
.fkid--info { border-left-color: var(--input-border-color); }
.fkid--more { border-style: dashed; border-left-width: 1px; color: var(--cta); font-size: 12px; font-weight: var(--w-clickable); align-items: center; }
.fkid__label { font-size: 12px; font-weight: var(--w-clickable); color: var(--heading); line-height: 1.3; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fkid__sub { font-size: 11px; color: var(--disclaimer); line-height: 1.3; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* lines inside popups */
.fnode__lines { list-style: none; margin: 8px 0 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
.fline { display: grid; grid-template-columns: 14px 1fr; gap: 6px; font-size: 12.5px; line-height: 1.4; color: var(--copy-text); word-break: break-word; }
.fline__mark { width: 14px; height: 14px; margin-top: 1px; border-radius: 50%; position: relative; background: var(--surface-background-secondary); border: 1px solid var(--border); }
.fline--ok .fline__mark { background: var(--success); border-color: var(--success); }
.fline--ok .fline__mark::after { content: ""; position: absolute; left: 4px; top: 1.5px; width: 3px; height: 6px; border: solid #fff; border-width: 0 1.6px 1.6px 0; transform: rotate(45deg); }
.fline--fail .fline__mark { background: var(--warning); border-color: var(--warning); }
.fline--fail .fline__mark::after { content: "!"; position: absolute; inset: 0; display: grid; place-items: center; color: #fff; font-size: 9px; font-weight: 700; }
.fline--info .fline__mark::after { content: ""; position: absolute; left: 4px; top: 4px; width: 4px; height: 4px; border-radius: 50%; background: var(--muted-soft); }
.fline--skip { color: var(--disclaimer); }
.fline--skip span:last-child { text-decoration: line-through; text-decoration-color: var(--muted-soft); }
.fnode__handover { margin-top: 8px; font-size: 11.5px; font-weight: 500; color: var(--cta); background: var(--cta-soft); border-radius: 6px; padding: 3px 7px; display: inline-block; }
.fnode__note { margin-top: 8px; padding: 6px 8px; border-radius: 8px; font-size: 12px; line-height: 1.45; background: var(--surface-background-secondary); color: var(--text-2); }

/* ------------------------------------------------------------------ popup (fixed, outside the scroll lane) */
.pop { position: fixed; z-index: 60; width: min(340px, calc(100vw - 16px)); max-height: min(420px, calc(100vh - 16px)); display: flex; flex-direction: column;
  background: #fff; border: 1px solid var(--border); border-radius: 12px; box-shadow: var(--shadow-float); animation: pop-in 0.16s var(--ease) both; }
@keyframes pop-in { from { opacity: 0; transform: translateY(-4px) scale(0.98); } to { opacity: 1; transform: none; } }
.pop__head { display: flex; justify-content: space-between; gap: 8px; padding: 12px 14px 8px; border-bottom: 1px solid var(--border); }
.pop__title { font-size: 14px; font-weight: var(--w-clickable); color: var(--heading); }
.pop__sub { font-size: 12px; color: var(--disclaimer); margin-top: 1px; word-break: break-word; }
.pop__close { width: 26px; height: 26px; flex: none; border: 0; border-radius: 7px; background: var(--surface-background-secondary); cursor: pointer; font-size: 16px; line-height: 1; color: var(--text-2); }
.pop__close:hover { background: var(--neutral-background); color: var(--heading); }
.pop__body { padding: 10px 14px 14px; overflow-y: auto; font-size: 13px; line-height: 1.5; display: flex; flex-direction: column; gap: 6px; }
.pop__muted { color: var(--disclaimer); font-size: 12px; }
.pop__list { margin: 0; padding-left: 16px; display: flex; flex-direction: column; gap: 6px; }
.pop__kv { margin: 0; display: flex; flex-direction: column; gap: 6px; }
.pop__kv > div { display: grid; grid-template-columns: 84px 1fr; gap: 8px; }
.pop__kv dt { color: var(--disclaimer); font-size: 12px; }
.pop__kv dd { margin: 0; }

/* ------------------------------------------------------------------ request log */
.flog { border-top: 1px solid var(--border); margin: 0 -18px -14px; }
.flog > summary { list-style: none; display: flex; align-items: center; gap: 8px; padding: 10px 18px; font-size: 13px; cursor: pointer; }
.flog > summary::-webkit-details-marker { display: none; }
.flog > summary::before { content: ""; width: 6px; height: 6px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; transform: rotate(-45deg); transition: transform 0.2s var(--ease); }
