.report__move { margin-top: 8px; font-size: var(--fs-small); color: var(--text-2); }
.report__headline { margin-top: 14px; padding-top: 12px; border-top: 1px solid rgba(16, 24, 40, 0.08); }
.report__label { font-size: 12px; font-weight: var(--w-clickable); color: var(--text-2); margin-bottom: 4px; }
.report__h { font-size: 17px; }
.report__hint { margin-top: 2px; font-size: 13px; color: var(--disclaimer); }
.report__briefhead { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.report__verified { font-size: 12.5px; font-weight: 500; color: var(--success); }
.report__tech > summary { font-size: 13px; }
.report__tech > p { margin-top: 8px; }

.recgroups { margin-top: 12px; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.recgroup { padding: 14px 16px; border-radius: 12px; border: 1px solid var(--border); border-top-width: 4px; background: #fff; }
.recgroup--go { border-top-color: var(--success); }
.recgroup--maybe { border-top-color: var(--cta); }
