.recgroup--unknown { border-top-color: var(--warning); }
.recgroup--na { border-top-color: var(--border); background: var(--surface-background-secondary); }
.recgroup__head { display: flex; justify-content: space-between; align-items: baseline; }
.recgroup__label { font-weight: var(--w-clickable); color: var(--heading); font-size: 15px; }
.recgroup__n { font-size: 20px; font-weight: 700; color: var(--heading); }
.recgroup__meaning { margin-top: 2px; font-size: 13px; color: var(--text-2); }
.recgroup__places { margin: 10px 0 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 4px; font-size: 13.5px; }
.recgroup__score { color: var(--disclaimer); font-size: 12px; }
.recgroup__action { margin-top: 8px; font-size: 12.5px; color: var(--text-2); }
.side__group--go { background: var(--success-background); }
.side__group--maybe { background: var(--cta-soft); }
.side__group--low, .side__group--na { background: var(--surface-background-secondary); }
.side__group--unknown { background: var(--warning-background); }

.plainfacts { margin: 12px 0 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.plainfacts > div { padding: 12px 14px; border-radius: 12px; background: var(--surface-background-secondary); }
.plainfacts dt { font-size: 12.5px; font-weight: var(--w-clickable); color: var(--text-2); }
.plainfacts dd { margin: 4px 0 0; font-size: 14px; line-height: 1.5; color: var(--copy-text); }
@media (max-width: 767px) { .plainfacts { grid-template-columns: 1fr; } }

.briefsecs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
@media (max-width: 900px) { .briefsecs { grid-template-columns: 1fr; } }
.briefsec { padding: 14px 16px; border-radius: 12px; border: 1px solid var(--border); }
.briefsec--next { grid-column: 1 / -1; background: var(--cta-soft); border-color: var(--cta-border); }
.briefsec__title { font-size: 15px; font-weight: var(--w-clickable); }
.briefsec__hint { font-size: 12px; color: var(--disclaimer); margin-bottom: 8px; }
.briefsec__claims { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 8px; }
.briefsec__claims .claim__text { font-size: 14px; line-height: 1.55; }
.briefsec--next .briefsec__claims { list-style: decimal; }
.report .note .spinner { vertical-align: -2px; margin-right: 6px; }

/* ------------------------------------------------------------------ small screens */
@media (max-width: 767px) {
  .flow__lane { grid-template-columns: 1fr; row-gap: 26px; min-width: 0; }
